import{z as s,x as i,o as B,c as d,q as l,j as r,D as a,d as t,s as n,S as o,b as e}from"./chunks/framework.C8m1ZpeB.js";const f=JSON.parse('{"title":"税与交易成本","description":"","frontmatter":{"title":"税与交易成本","date":"2026-09-18T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/gm-tax-costs.md","filePath":"quant/gm-tax-costs.md","lastUpdated":1791413859000}'),m={name:"quant/gm-tax-costs.md"};function p(C,E,D,u,F,T){const A=i("Mermaid");return B(),d("div",null,[E[2]||(E[2]=l('<h1 id="税与交易成本" tabindex="-1">税与交易成本 <a class="header-anchor" href="#税与交易成本" aria-label="Permalink to &quot;税与交易成本&quot;">​</a></h1><div class="epigraph"><p>价差是市场给的，税是设计出来的：交易税的目的本来就是改变行为——所以把它当价差的加法项建模是错的，它改变的是换手、持有期与场所选择本身。</p><footer>—— 据 Umlauf, Journal of Financial Economics, 1993；Campbell and Froot, 1994 的交易税实证传统整理</footer></div><p><a href="/quant/gm-clearing-settlement">上一课</a>把成交之后的链条写成制度常量。本课把账单写全：显式费用（佣金、平台、清算）与隐式成本（价差、冲击、时机）在执行课程的 TCA 口径里已处理；剩下的最大一笔是税——它在不同市场取完全不同的形态，且只对行为起作用。本课写税作为成本与约束的机制，继续机制单元的对照口径。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>同一策略在五个市场的排序可以仅因税不同而翻转：港股与 A 股的印花税按边计征，印度 STT 分边分品种，英国在买入侧征千分之五量级的印花税，法国意大利有大额股的金融交易税，美国没有联邦交易税但有监管费转嫁——同时美国税法用三十天洗售规则惩罚「卖出后买回」，税损收割的日历由税法生成。缺口在于成本模型普遍把税写成常数项：一笔按边比例的换手税，乘上换手率就完事。这漏掉两层：其一，税改变均衡——交易税提高后成交量下降、活动迁往免税场所或品种（瑞典交易税把成交推走是经典案例，Umlauf 1993；多国比较见 Campbell and Froot 1994）；其二，税改变日历——洗售与持有期规则直接生成最优再平衡的时点集。只算比例不算行为，税后排序就是错的。</p><p><span class="marginnote">比较策略变体时必须报税前与税后两列：高换手变体在无交易税样本里领先，加上双边印花税后排序可以整体翻转——把税前列当结论，迁移到港股或印度的第一天就会发现方向反了。</span></p><p><span class="marginnote">数字实例：一个日均双边换手 50% 的策略，在印花税双边各 0.1% 的市场一年约 250 个交易日，仅印花税就是 \\(0.5\\times0.2\\%\\times250=25\\%\\) 的年化拖累——而同一策略在无交易税的市场只需付佣金与价差，年化可能只有 3%。「排序翻转」不是边际修正，是可以翻 20 个百分点的量级。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>把税写进成本模型的三层。第一层是换手税：逐边逐品种归档税率与计税基础（成交额或差价），进入每笔交易的事后会计——与 maker-taker 的处理一样，税后的经济账才用于场所与策略比较（<a href="/quant/maker-taker">maker-taker</a>）。第二层是规则税：洗售窗口、持有期档位、损失抵扣限制写成状态机，输出「哪些再平衡时点会被税务惩罚」的日历；税损收割策略的收益上限由这个日历决定，不由信号决定。第三层是预扣与持有结构：股息预扣税率按持券结构与税收协定归档，跨境持券的国别选择部分由预扣决定。三层都按当期税则归档并带日期——税则是本课程里变动最频繁的参数。</p><p><span class="marginnote">「洗售规则」翻译成白话：美国税法规定，卖出亏钱资产前后 30 天内又买回「实质相同」的资产，这笔亏损不能用来抵税。术语叫 wash sale——「洗」的就是想把亏损洗出来报税的动作。所以税损收割（年底卖亏仓抵税）要么等过 31 天再买回，要么换一只「相似但不相同」的标的保持敞口。</span></p>',10)),(B(),r(o,null,{default:a(()=>[n(A,{id:"mermaid-28",class:"mermaid",graph:"flowchart%20TD%0A%20%20EX%5B%22%E6%98%BE%E5%BC%8F%E8%B4%B9%E7%94%A8%EF%BC%9A%E4%BD%A3%E9%87%91%2F%E5%B9%B3%E5%8F%B0%2F%E6%B8%85%E7%AE%97%22%5D%20--%3E%20PRE%5B%22%E7%A8%8E%E5%89%8D%E6%88%90%E6%9C%AC%22%5D%0A%20%20IM%5B%22%E9%9A%90%E5%BC%8F%E6%88%90%E6%9C%AC%EF%BC%9A%E4%BB%B7%E5%B7%AE%2F%E5%86%B2%E5%87%BB%2F%E6%97%B6%E6%9C%BA%22%5D%20--%3E%20PRE%0A%20%20TX%5B%22%E6%8D%A2%E6%89%8B%E7%A8%8E%EF%BC%9A%E5%8D%B0%E8%8A%B1%E7%A8%8E%20%2F%20STT%20%2F%20FTT%22%5D%20--%3E%20POST%5B%22%E7%A8%8E%E5%90%8E%E6%88%90%E6%9C%AC%22%5D%0A%20%20WH%5B%22%E8%82%A1%E6%81%AF%E9%A2%84%E6%89%A3%E4%B8%8E%E6%8C%81%E6%9C%89%E7%BB%93%E6%9E%84%22%5D%20--%3E%20POST%0A%20%20PRE%20--%3E%20RANK%5B%22%E7%AD%96%E7%95%A5%E6%8E%92%E5%BA%8F%22%5D%0A%20%20POST%20--%3E%20RANK%0A%20%20WS%5B%22%E6%B4%97%E5%94%AE%E4%B8%8E%E6%8C%81%E6%9C%89%E6%9C%9F%E8%A7%84%E5%88%99%22%5D%20--%3E%20CAL%5B%22%E7%A8%8E%E6%B3%95%E7%94%9F%E6%88%90%E7%9A%84%E5%86%8D%E5%B9%B3%E8%A1%A1%E6%97%A5%E5%8E%86%22%5D%0A%20%20TX%20--%3E%20BEH%5B%22%E8%A1%8C%E4%B8%BA%E5%8F%8D%E5%BA%94%EF%BC%9A%E6%8D%A2%E6%89%8B%E4%B8%8E%E5%9C%BA%E6%89%80%E8%BF%81%E7%A7%BB%22%5D%0A"})]),fallback:a(()=>[...E[0]||(E[0]=[t(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=e("h2",{id:"机制",tabindex:"-1"},[t("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),E[4]||(E[4]=e("p",null,"税的行为机制走两条路。价格路径：交易税抬高做市的库存持有成本，报价进价差、深度收缩——税的一部分由流动性消费者以更宽的价差支付，所以「只对卖方征税」从来不是只由卖方承担。数量路径：高换手策略对税的弹性最大，边际信号被税吃掉后退出交易，市场活动向免税场所与品种迁移；成交量本身因此是税制的结果变量，跨市场比较成交量时要把税制当解释变量。港股印花税先调高后调减提供了少见的双向自然实验窗口：调高后换手敏感品种的活动收缩、调减后回补——方向与弹性都可检验。洗售规则的机制更直接：它把「成本」变成「可行时点集」，约束优化里的日历约束比费率参数更硬。不这么做会错在哪：把税当常数，会同时错三件事——费后排序、容量估计（税后可交易的边际信号变少）、以及税损策略的日历。",-1)),E[5]||(E[5]=e("p",null,"「只对卖方征税、为何买卖双方都付费」这条分摊链回答的是「税负到底落在谁头上」：",-1)),(B(),r(o,null,{default:a(()=>[n(A,{id:"mermaid-38",class:"mermaid",graph:"flowchart%20TD%0A%20%20TAX%5B%22%E5%8D%96%E6%96%B9%E8%A2%AB%E5%BE%81%E4%BA%A4%E6%98%93%E7%A8%8E%22%5D%20--%3E%20INV%5B%22%E5%8D%96%E6%96%B9%E5%BA%93%E5%AD%98%E6%8C%81%E6%9C%89%E6%88%90%E6%9C%AC%E4%B8%8A%E5%8D%87%22%5D%0A%20%20INV%20--%3E%20QM%5B%22%E5%81%9A%E5%B8%82%E5%95%86%E5%8A%A0%E5%AE%BD%E6%8A%A5%E4%BB%B7%20%E6%94%B6%E7%AA%84%E6%B7%B1%E5%BA%A6%22%5D%0A%20%20QM%20--%3E%20BUY%5B%22%E4%B9%B0%E6%96%B9%E4%BB%98%E6%9B%B4%E5%AE%BD%E4%BB%B7%E5%B7%AE%22%5D%0A%20%20BUY%20--%3E%20LESS%5B%22%E6%88%90%E4%BA%A4%E6%84%8F%E6%84%BF%E4%B8%8B%E9%99%8D%22%5D%0A%20%20LESS%20--%3E%20VOL%5B%22%E6%88%90%E4%BA%A4%E9%87%8F%E8%90%8E%E7%BC%A9%20%E7%A8%8E%E5%9F%BA%E5%8F%98%E5%B0%8F%22%5D%0A%20%20VOL%20-.-%3E%7C%22%E8%A1%8C%E4%B8%BA%E5%8F%8D%E9%A6%88%22%7C%20TAX%0A"})]),fallback:a(()=>[...E[1]||(E[1]=[t(" Loading... ",-1)])]),_:1})),E[6]||(E[6]=l('<p><span class="marginnote">直觉类比：交易税像往河道里筑一道低坝——水不会消失，只会改道。瑞典当年的交易税把大量成交赶到伦敦的免税场所，本国税基反而萎缩；「筑坝的人想截流，水却从旁边的干河道走了」。这就是为什么税率的静态测算总会高估税收、低估行为反应。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课口径是「税作为成本与约束」，不是税务筹划与合规意见；个人报税、预扣返还流程、机构税收居民身份问题不写。税率、窗口与档位以各税区当期文本为准，清单随日期失效。税与费用对做市库存模型的具体耦合，在做市课程已处理的不重复。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>税不是价差的加法项：它通过行为改变换手、深度与场所选择。</li><li>成本模型分三层：换手税入笔账、规则税生成日历、预扣决定持有结构。</li><li>报告税前与税后两列排序；换手敏感策略的排序可以因双边印花税整体翻转。</li><li>洗售与持有期规则把成本写成状态机，税损收割的上限由税法日历决定。</li><li>出处：Umlauf, <em>Journal of Financial Economics</em>, 1993（瑞典）；Campbell and Froot, 1994（多国比较）；Pomeranets and Weaver 对多伦多交易税的实证；各税区公开税则口径。</li></ul>',5))])}const h=s(m,[["render",p]]);export{f as __pageData,h as default};
